/*
 * A321104  Sequence generated by: a(3*n) = 1, a(3*n+2) = 2 - a(3*n+1),
 *          a(9*n+1) = 0, a(9*n+7) = 2, a(9*n+4) = 2 - a(3*n+1), for n >= 0.
 * https://oeis.org/A321104
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 200, u16 n <= 200, u32 n <= 200, u64 n <= 200,
 *            u128 n <= 200, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A321104:
 *   a(3*n)     = 1,
 *   a(3*n+2)   = 2 - a(3*n+1),
 *   a(9*n+1)   = 0,
 *   a(9*n+7)   = 2,
 *   a(9*n+4)   = 2 - a(3*n+1)   (for n ≥ 0) */

#include <stddef.h>
#include <stdlib.h>

/* Ensure *ptr points to an array that can hold at least 'need' elements.
 * Expands the array if necessary.  The array is allocated with malloc/realloc.
 */
static void _ensure_cache(idx_t need, size_t *cap, seq_t **ptr)
{
    if ((idx_t)*cap >= need)
        return;
    size_t new_cap = need;
    seq_t *tmp = (seq_t *)realloc(*ptr, new_cap * sizeof(seq_t));
    if (!tmp)
    {
        abort();                /* allocation failure – terminate safely */
    }
    *ptr   = tmp;
    *cap   = new_cap;
}

seq_t a(idx_t n)
{
    /* Static cache of computed values */
    static seq_t *cache = NULL;    /* array of a(0) .. a(max-1) */
    static size_t cap   = 0;       /* capacity of cache array (elements) */
    static idx_t computed = 0;     /* number of values already computed */

    /* Make sure we have room for indices up to 'n' */
    _ensure_cache(n + 1, &cap, &cache);

    /* Compute any missing values up to n */
    if (computed <= n)
    {
        for (idx_t i = computed; i <= n; ++i)
        {
            /* a(3*n) = 1 */
            if ((i % 3) == 0)
            {
                cache[i] = 1;
            }
            /* a(9*n+1) = 0 */
            else if ((i % 9) == 1)
            {
                cache[i] = 0;
            }
            /* a(9*n+7) = 2 */
            else if ((i % 9) == 7)
            {
                cache[i] = 2;
            }
            /* a(9*n+4) = 2 - a(3*n+1) */
            else if ((i % 9) == 4)
            {
                idx_t m = (i - 4) / 9;          /* compute the n in 9*n+4 */
                idx_t ref = 3 * m + 1;          /* 3*n+1 */
                cache[i] = 2 - cache[ref];
            }
            /* a(3*n+2) = 2 - a(3*n+1)  (remaining indices) */
            else
            {
                cache[i] = 2 - cache[i - 1];
            }
        }
        computed = n + 1;
    }

    return cache[n];
}
